// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        // bound version to avoid unrealistic values
        version = bound(version, 0, 1000);

        // Get the oracle address via atVersion
        // We need to call atVersion, which internally uses oracle()
        // even if version is out of range, the call should complete (or revert) - we want the oracle address check
        // Since atVersion calls oracle().atVersion(version), and oracle() returns the address,
        // we can get the oracle address from the oracle() public view function directly
        // The bug changes oracle() to return address(0), so we check that.
        (bool success, bytes memory result) = address(c).staticcall(abi.encodeWithSignature("oracle()"));
        assertTrue(success, "oracle() call failed");
        address oracleAddr = abi.decode(result, (address));

        // General rule: oracle() must return a contract address (code length > 0)
        assertTrue(oracleAddr.code.length > 0, "oracle() must return a contract");
    }
}

