pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        // Filter out versions that would cause the oracle to revert (e.g., version 0 might be invalid)
        vm.assume(version > 0);
        // We need to ensure that atVersion does not revert. In the reference, it may revert for some versions;
        // we assume it returns successfully (i.e., the version is within a valid range).
        // We'll try to call atVersion and catch reverts.
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSignature("atVersion(uint256)", version));
        vm.assume(success);
        // Decode the return value (OracleVersion struct: version uint256, timestamp uint256, price int256)
        (uint256 retVersion, uint256 timestamp, int256 price) = abi.decode(data, (uint256, uint256, int256));
        // General rule: price must be >= 0 (non-negative)
        assertTrue(price >= 0, "Price should be non-negative");
    }
}

