import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oracleVersion) public {
        vm.assume(oracleVersion <= 100); // avoid unrealistic versions

        // Get the transformed price from the product
        (uint256 prodVersion, uint256 prodTimestamp, int256 prodPrice) = c.atVersion(oracleVersion);

        // Get the raw oracle price
        (uint256 rawVersion, uint256 rawTimestamp, int256 rawPrice) = c.oracle().atVersion(oracleVersion);

        // Get the payoff definition
        (uint8 payoffType, uint8 payoffDirection, bytes30 data) = c.payoffDefinition();

        // The product's price should equal the transformed raw price
        // For a simple payoff definition (e.g., identity), transform returns the same price
        // But we can only check that the version and timestamp match
        assertTrue(prodVersion == rawVersion && prodTimestamp == rawTimestamp);
    }
}

